  async upsertAiProviderSettings(input: Omit<AiProviderSettings, "updatedAt">) { const result = await this.pool.query("INSERT INTO gbolix_ai_provider_settings (agent_id,workspace_id,provider_order,models,fallback_enabled,auto_update_models) VALUES ($1,$2,$3,$4,$5,$6) ON CONFLICT (agent_id) DO UPDATE SET workspace_id=EXCLUDED.workspace_id,provider_order=EXCLUDED.provider_order,models=EXCLUDED.models,fallback_enabled=EXCLUDED.fallback_enabled,auto_update_models=EXCLUDED.auto_update_models,updated_at=NOW() RETURNING *", [input.agentId, input.workspaceId, JSON.stringify(input.providerOrder), JSON.stringify(input.models), input.fallbackEnabled, input.autoUpdateModels]); return aiProviderSettingsRow(result.rows[0]); }
