  async upsertAiProvider(input: { id: string; name: string; adapter: AiProviderAdapter; baseUrl: string; encryptedApiKey?: string; defaultModel: string; priority: number; enabled: boolean }) { const result = await this.pool.query("INSERT INTO gbolix_ai_providers (id,name,adapter,base_url,encrypted_api_key,default_model,priority,enabled) VALUES ($1,$2,$3,$4,$5,$6,$7,$8) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name,adapter=EXCLUDED.adapter,base_url=EXCLUDED.base_url,encrypted_api_key=COALESCE(EXCLUDED.encrypted_api_key,gbolix_ai_providers.encrypted_api_key),default_model=EXCLUDED.default_model,priority=EXCLUDED.priority,enabled=EXCLUDED.enabled,updated_at=NOW() RETURNING *", [input.id, input.name, input.adapter, input.baseUrl, input.encryptedApiKey ?? null, input.defaultModel, input.priority, input.enabled]); return aiProviderRow(result.rows[0]); }
