  async createEmailCampaign(input: Omit<EmailCampaign, "id" | "createdAt" | "updatedAt" | "sentRows" | "failedRows">) { const result = await this.pool.query("INSERT INTO gbolix_email_campaigns (id,agent_id,workspace_id,status,subject_template,body_template,message_mode,total_rows) VALUES ($1,$2,$3,$4,$5,$6,$7,$8) RETURNING *", [id("campaign"), input.agentId, input.workspaceId, input.status, input.subjectTemplate, input.bodyTemplate, input.messageMode, input.totalRows]); return emailCampaignRow(result.rows[0]); }
